import { circularProgressClasses } from '@mui/material/CircularProgress';
import type { Theme } from '@mui/material/styles';
import type { SystemStyleObject } from '@mui/system';
import { svTokens } from '../../theme/tokens';

export function buttonSize(size: string | undefined) {
  return size === 'small' ? 28 : size === 'large' ? 44 : 36;
}

export function buttonColors(theme: Theme, color: string) {
  const palette = (theme.vars ?? theme).palette;
  const colored = palette[color as keyof typeof palette];
  const swatch =
    typeof colored === 'object' && colored && 'main' in colored
      ? colored
      : undefined;
  return {
    main:
      color === 'inherit'
        ? 'currentColor'
        : `var(--SvButton-${color}, ${swatch?.main ?? palette.primary.main})`,
    hover:
      color === 'inherit'
        ? 'currentColor'
        : `var(--SvButton-${color}Hover, ${swatch && 'dark' in swatch ? swatch.dark : palette.primary.dark})`,
    contrast:
      color === 'inherit'
        ? 'inherit'
        : `var(--SvButton-${color}Contrast, ${swatch && 'contrastText' in swatch ? swatch.contrastText : '#fff'})`,
  };
}

export function buttonFocus(theme: Theme): SystemStyleObject<Theme> {
  return {
    outline: `2px solid ${svTokens(theme).focus}`,
    outlineOffset: '3px',
  };
}

export const buttonReducedMotion: SystemStyleObject<Theme> = {
  animation: 'none',
  transition: 'none',
  '&::before': { animation: 'none' },
  [`& .${circularProgressClasses.root}, & .${circularProgressClasses.circle}`]:
    { animation: 'none' },
};
